// Phase 5 Wave 0 pins (CAT-01, CAT-03; BEH-EA-231/233/324/339): today's core-table lists, the RLS
// coverage they produce, the six sealed declarations with their AADs, and the tables the core migrations
// create. Written against the pre-catalogue lists and green before and after the catalogue.
// The expected side of every assertion is inline text on purpose: a file snapshot can be regenerated by
// `vitest -u`, an inline literal cannot. This file is never edited after its add commit.
// Runs on SQLite, and on Postgres under `AWTHAQ_POSTGRES_URL` (the same file, `TestSql.layer` picks the database).
import { assert, describe, it } from "@effect/vitest";
import * as Effect from "effect/Effect";
import * as Migrator from "effect/sql/Migrator";
import * as CoreMigrations from "../src/CoreMigrations.ts";
import * as CoreSealedColumns from "../src/CoreSealedColumns.ts";
import * as RateLimiterStoreSql from "../src/RateLimiterStoreSql.ts";
import * as SealedColumn from "../src/SealedColumn.ts";
import * as TenantScope from "../src/TenantScope.ts";
import * as TenantScoped from "../src/TenantScoped.ts";
import * as TestSql from "../../test/src/TestSql.ts";

// Both lists are compared through `ReadonlyArray<string>`, so the file type-checks whether they are tuples or arrays.
const names = (list: ReadonlyArray<string>): ReadonlyArray<string> => [...list];

// The shapes `coverage` returns; spelled out per entry in the expected literals below.
const column = (table: string, on: string) => ({ table, kind: "column" as const, column: on });
const tenant = (table: string) => column(table, "tenantId");
const derived = (table: string, parent: string, via: string) => ({
  table,
  kind: "parent" as const,
  parent,
  via,
  parentKey: "id",
});

// Copied verbatim from `TenantScoped.test.ts` (the `TenantScope.coverage` describe).
const declared = [
  { plugin: "webhooks", table: "webhooks_endpoint", tenancy: TenantScoped.partitioned() },
  {
    plugin: "webhooks",
    table: "webhooks_delivery",
    tenancy: TenantScoped.derived("webhooks_endpoint", "endpointId"),
  },
  { plugin: "organization", table: "organization_org", tenancy: TenantScoped.keyed("id") },
  {
    plugin: "organization",
    table: "organization_team",
    tenancy: TenantScoped.keyed("organizationId"),
  },
  {
    plugin: "organization",
    table: "organization_team_membership",
    tenancy: TenantScoped.derived("organization_team", "teamId"),
  },
  {
    plugin: "organization",
    table: "organization_active_context",
    tenancy: TenantScoped.derived("sessions", "sessionId"),
  },
  { plugin: "jwt", table: "jwt_signing_key", tenancy: TenantScoped.global("deployment-wide") },
];

const corePartitioned = [
  tenant("sessions"),
  tenant("verification_tokens"),
  tenant("verification_reservations"),
  tenant("auth_audit_log"),
];
const coreDirectory = [tenant("users"), tenant("accounts")];

describe("CoreTablePins", () => {
  it("P1: the two TenantScope lists and their order", () => {
    assert.deepStrictEqual(names(TenantScope.partitionedTables), [
      "sessions",
      "verification_tokens",
      "verification_reservations",
      "auth_audit_log",
    ]);
    assert.deepStrictEqual(names(TenantScope.directoryTables), ["users", "accounts"]);
  });

  describe("P2: TenantScope.coverage output, frozen from a real run", () => {
    it("default options: the four partitioned tables", () => {
      assert.deepStrictEqual(TenantScope.coverage(undefined), {
        covered: corePartitioned,
        skipped: [],
      });
    });

    it("includeDirectory: the directory tables follow, in order", () => {
      assert.deepStrictEqual(TenantScope.coverage({ includeDirectory: true }), {
        covered: [...corePartitioned, ...coreDirectory],
        skipped: [],
      });
    });

    it("plugins: a Derived table under an uncovered Keyed parent is skipped, and says so", () => {
      assert.deepStrictEqual(TenantScope.coverage({ plugins: declared }), {
        covered: [
          ...corePartitioned,
          tenant("webhooks_endpoint"),
          derived("webhooks_delivery", "webhooks_endpoint", "endpointId"),
          derived("organization_active_context", "sessions", "sessionId"),
        ],
        skipped: [
          {
            table: "organization_team_membership",
            reason: "its parent table is not covered by this call",
          },
        ],
      });
    });

    it("plugins and includeKeyed: Keyed tables, then the Derived tables beneath them", () => {
      assert.deepStrictEqual(TenantScope.coverage({ plugins: declared, includeKeyed: true }), {
        covered: [
          ...corePartitioned,
          tenant("webhooks_endpoint"),
          column("organization_org", "id"),
          column("organization_team", "organizationId"),
          derived("webhooks_delivery", "webhooks_endpoint", "endpointId"),
          derived("organization_team_membership", "organization_team", "teamId"),
          derived("organization_active_context", "sessions", "sessionId"),
        ],
        skipped: [],
      });
    });

    it("includeDirectory, plugins and includeKeyed together", () => {
      assert.deepStrictEqual(
        TenantScope.coverage({ includeDirectory: true, plugins: declared, includeKeyed: true }),
        {
          covered: [
            ...corePartitioned,
            ...coreDirectory,
            tenant("webhooks_endpoint"),
            column("organization_org", "id"),
            column("organization_team", "organizationId"),
            derived("webhooks_delivery", "webhooks_endpoint", "endpointId"),
            derived("organization_team_membership", "organization_team", "teamId"),
            derived("organization_active_context", "sessions", "sessionId"),
          ],
          skipped: [],
        },
      );
    });
  });

  describe("P3: the six sealed declarations", () => {
    // [table, column, key, adoptPlaintext, rendered AAD for row id "<id>"]
    const render = (declared: ReadonlyArray<SealedColumn.Sweepable>) =>
      declared.map((sealed) => [
        sealed.table,
        sealed.column,
        sealed.key,
        sealed.adoptPlaintext === true,
        SealedColumn.aadOf(sealed, "<id>"),
      ]);
    const providerTokens = [
      ["accounts", "accessToken", "id", false, "accounts:<id>:accessToken"],
      ["accounts", "refreshToken", "id", false, "accounts:<id>:refreshToken"],
      ["accounts", "idToken", "id", false, "accounts:<id>:idToken"],
    ];

    it("deployed with encryptPii: provider tokens first, then the three personal-data columns", () => {
      assert.deepStrictEqual(render(CoreSealedColumns.deployed({ encryptPii: true })), [
        ...providerTokens,
        ["users", "metadata", "id", true, "users:<id>:metadata"],
        ["sessions", "ipAddress", "id", true, "sessions:<id>:ipAddress"],
        ["sessions", "userAgent", "id", true, "sessions:<id>:userAgent"],
      ]);
    });

    it("deployed without encryptPii: the provider tokens only", () => {
      assert.deepStrictEqual(
        render(CoreSealedColumns.deployed({ encryptPii: false })),
        providerTokens,
      );
    });
  });

  describe("P4: the tables the core migrations create", () => {
    it.effect("the core migrations, then the rate limiter's, create exactly these tables", () =>
      Effect.gen(function* () {
        const tables = Effect.map(TestSql.schemaOf, (shape) => Object.keys(shape.tables).sort());
        yield* Migrator.make({})({ loader: CoreMigrations.coreMigrations });
        assert.deepStrictEqual(yield* tables, [
          "accounts",
          "auth_audit_log",
          "auth_relay_cursor",
          "sessions",
          "users",
          "verification_reservations",
          "verification_tokens",
        ]);
        // The raw `schemaOf` output: the rate limiter's own ledger is a table too. This pin records what exists.
        yield* RateLimiterStoreSql.migrate;
        assert.deepStrictEqual(yield* tables, [
          "accounts",
          "auth_audit_log",
          "auth_relay_cursor",
          "awthaq_rate_limiter_migrations",
          "rate_limit_buckets",
          "sessions",
          "users",
          "verification_reservations",
          "verification_tokens",
        ]);
      }).pipe(Effect.provide(TestSql.layer("sql_CoreTablePins"))),
    );
  });
});
